import { db } from '@/firebase';
import {
  addDoc,
  collection,
  serverTimestamp,
  query,
  where,
  updateDoc,
  doc,
  getDocs,
  getDocsFromCache,
  onSnapshot,
  type QuerySnapshot,
} from 'firebase/firestore';

export type Broadcast = {
  id?: string;
  title: string;
  message: string;
  audienceKey: string; // 'global' أو 'shop:<shopId>'
  active: boolean;
  createdAt?: any;
  createdBy?: string;
  linkUrl?: string;
  actionText?: string;
};

export async function publishBroadcast({ title, message, audienceKey, createdBy, linkUrl, actionText }: { title: string; message: string; audienceKey: string; createdBy?: string; linkUrl?: string; actionText?: string; }) {
  const payload: Broadcast = {
    title,
    message,
    audienceKey,
    active: true,
    createdAt: serverTimestamp(),
    createdBy: createdBy || null as any,
    linkUrl: linkUrl || undefined,
    actionText: actionText || undefined,
  };
  const ref = await addDoc(collection(db, 'broadcasts'), payload as any);
  return ref.id;
}

export async function fetchActiveBroadcasts(audienceKeys: string[]): Promise<Broadcast | null> {
  try {
    const { getDocs } = await import('firebase/firestore');
    const promises = audienceKeys.map(key => {
      const q = query(collection(db, 'broadcasts'), where('audienceKey', '==', key));
      return getDocs(q);
    });

    const snapshots = await Promise.all(promises);
    const allActive: Broadcast[] = [];

    snapshots.forEach(snap => {
      snap.forEach(doc => {
        const data = doc.data() as Broadcast;
        if (data.active) {
          allActive.push({ ...data, id: doc.id });
        }
      });
    });

    if (allActive.length === 0) return null;

    // ترتيب حسب createdAt (الأحدث أولاً)
    allActive.sort((a, b) => {
      const ta = typeof a.createdAt?.toMillis === 'function' ? a.createdAt.toMillis() : 0;
      const tb = typeof b.createdAt?.toMillis === 'function' ? b.createdAt.toMillis() : 0;
      return ta - tb;
    });

    return allActive[allActive.length - 1]; // إرجاع الأحدث
  } catch (error) {
    console.error('fetchActiveBroadcasts error:', error);
    return null;
  }
}

export function subscribeToActiveBroadcasts(audienceKeys: string[], cb: (b: Broadcast | null) => void) {
  // تم تحويلها لاستخدام الجلب مرة واحدة بدلاً من الاستماع المستمر لتوفير القراءات
  fetchActiveBroadcasts(audienceKeys).then(cb);
  return () => {};
}

export async function fetchActiveBroadcastsList(audienceKeys: string[]): Promise<Broadcast[]> {
  try {
    const { getDocs } = await import('firebase/firestore');
    const promises = audienceKeys.map(key => {
      const q = query(collection(db, 'broadcasts'), where('audienceKey', '==', key));
      return getDocs(q);
    });

    const snapshots = await Promise.all(promises);
    const docsMap = new Map<string, Broadcast>();

    snapshots.forEach(snap => {
      snap.forEach(doc => {
        const data = doc.data() as Broadcast;
        if (data.active) {
          docsMap.set(doc.id, { ...data, id: doc.id });
        }
      });
    });

    const allActive = Array.from(docsMap.values());
    return allActive.sort((a, b) => {
      const ta = typeof a.createdAt?.toMillis === 'function' ? a.createdAt.toMillis() : 0;
      const tb = typeof b.createdAt?.toMillis === 'function' ? b.createdAt.toMillis() : 0;
      return tb - ta; // الأحدث أولاً
    });
  } catch (error) {
    console.error('fetchActiveBroadcastsList error:', error);
    return [];
  }
}

export function subscribeToActiveBroadcastsList(audienceKeys: string[], cb: (list: Broadcast[]) => void) {
  // Re-enabled real-time listening as requested to ensure notifications appear on Web/PC immediately
  // when they arrive on Android (synced via Firestore).
  
  const cache = new Map<string, Broadcast[]>();
  const unsubscribers: (() => void)[] = [];

  const updateAndEmit = () => {
    const allDocs = new Map<string, Broadcast>();
    
    // Merge all lists from different audience keys
    cache.forEach((items) => {
      items.forEach(item => {
        if (item.id) allDocs.set(item.id, item);
      });
    });

    const allActive = Array.from(allDocs.values());
    // Sort by createdAt desc
    allActive.sort((a, b) => {
      const ta = typeof a.createdAt?.toMillis === 'function' ? a.createdAt.toMillis() : 0;
      const tb = typeof b.createdAt?.toMillis === 'function' ? b.createdAt.toMillis() : 0;
      return tb - ta;
    });

    cb(allActive);
  };

  audienceKeys.forEach((key) => {
    const q = query(collection(db, 'broadcasts'), where('audienceKey', '==', key));
    const applyQuerySnapshot = (snapshot: QuerySnapshot) => {
      const items: Broadcast[] = [];
      snapshot.forEach((d) => {
        const data = d.data() as Broadcast;
        if (data.active) {
          items.push({ ...data, id: d.id });
        }
      });
      cache.set(key, items);
      updateAndEmit();
    };
    const unsubscribe = onSnapshot(
      q,
      applyQuerySnapshot,
      (error) => {
        console.error(`Error in broadcast subscription for key ${key}:`, error);
        void (async () => {
          try {
            const snap = await getDocsFromCache(q);
            applyQuerySnapshot(snap);
          } catch {
            try {
              const list = await fetchActiveBroadcastsList([key]);
              cache.set(key, list);
              updateAndEmit();
            } catch {
              /* ignore */
            }
          }
        })();
      }
    );
    unsubscribers.push(unsubscribe);
  });

  return () => {
    unsubscribers.forEach(unsub => unsub());
  };
}

export async function deactivateBroadcast(id: string) {
  await updateDoc(doc(db, 'broadcasts', id), { active: false });
}